from __future__ import absolute_import
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException
from taf.selenium.sbts_fsm3.pages.panels.view import ViewPanel
from taf.selenium.sbts_fsm3.pages.modals import ConfigurationResetModal
from taf.selenium.sbts_fsm3.pages.navigatable_page import NavigatablePage


class ConfigurationResetPage(NavigatablePage):
    """
    As a class will be called by Configuration,
    all operations on Configuration Reset will be implemented under this class.
    """
    _CONFIG_RESET_BUTON_XPATH = '//ui-button[@a-text="Execute Reset"]'
    _MENU_ROUTE_LIST = ['Configuration', 'Configuration Reset']

    def __init__(self, driver):
        super(ConfigurationResetPage, self).__init__(driver)
        self._driver = driver
        self._view_panel = ConfigurationResetPageViewPanel(driver)

    def perform_config_reset(self, timeout=60):
        self._view_panel.click_config_reset(self._CONFIG_RESET_BUTON_XPATH, timeout)
        configurtion_reset_modal = ConfigurationResetModal(self._driver)
        configurtion_reset_modal.wait_until_reset_modal_appear(timeout)
        configurtion_reset_modal.confirm()
        return self._view_panel.get_reset_status(timeout)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class ConfigurationResetPageViewPanel(ViewPanel):
    RESET_SUCCEEDED_XPATH = '//div[contains(text(), "Execution succeeded")]'
    RESET_SUCCEEDED = "Execution succeeded"
    RESET_FAILED = "Execution failed"

    def __init__(self, driver):
        super(ConfigurationResetPageViewPanel, self).__init__(driver)

    def click_config_reset(self, xpath, timeout):
        self.click_enabled_element((By.XPATH, xpath), timeout)

    def get_reset_status(self, timeout):
        try:
            self.wait_for_visibility_by_xpath(self.RESET_SUCCEEDED_XPATH, timeout)
            return self.RESET_SUCCEEDED
        except TimeoutException:
            return self.RESET_FAILED
